28	import org.springframework.http.HttpHeaders;
29	import org.springframework.http.HttpStatus;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.mapper.OwnerMapper;
32	import org.springframework.samples.petclinic.mapper.PetMapper;
33	import org.springframework.samples.petclinic.mapper.VisitMapper;
34	import org.springframework.samples.petclinic.model.Owner;
35	import org.springframework.samples.petclinic.model.Pet;
36	import org.springframework.samples.petclinic.model.Visit;
37	import org.springframework.samples.petclinic.rest.api.OwnersApi;
38	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
39	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.PetDto;
41	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private final ClinicService clinicService;
63	
64	    private final OwnerMapper ownerMapper;
65	
66	    private final PetMapper petMapper;
67	
68	    private final VisitMapper visitMapper;
69	
70	    public OwnerRestControllerV1(ClinicService clinicService,
71	                                 OwnerMapper ownerMapper,
72	                                 PetMapper petMapper,
73	                                 VisitMapper visitMapper) {
74	        this.clinicService = clinicService;
75	        this.ownerMapper = ownerMapper;
76	        this.petMapper = petMapper;
77	        this.visitMapper = visitMapper;
78	    }
79	
80	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
81	    @Override
82	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
83	        Collection<Owner> owners;
84	        if (lastName != null) {
85	            owners = this.clinicService.findOwnerByLastName(lastName);
86	        } else {
87	            owners = this.clinicService.findAllOwners();
88	        }
89	        if (owners.isEmpty()) {
90	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
91	        }
92	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
98	        Owner owner = this.clinicService.findOwnerById(ownerId);
99	        if (owner == null) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
108	        HttpHeaders headers = new HttpHeaders();
109	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
110	        String address = normalizeAddress(owner.getAddress());
111	        if (address.isEmpty()) {
112	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
113	        }
114	        owner.setAddress(address);
115	        String telephone = toE164(owner.getTelephone());
116	        if (telephone == null) {
117	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
118	        }
119	        if (owner.getEmail() != null) {
120	            String email = normalizeEmail(owner.getEmail());
121	            if (email == null) {
122	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
123	            }
124	            owner.setEmail(email);
125	        }
126	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
127	            return new ResponseEntity<>(HttpStatus.CONFLICT);
128	        }
129	        for (Owner existing : this.clinicService.findAllOwners()) {
130	            if (telephone.equals(toE164(existing.getTelephone()))) {
131	                return new ResponseEntity<>(HttpStatus.CONFLICT);
132	            }
133	        }
134	        String lastNameKey = householdKey(owner.getLastName());
135	        String addressKey = householdKey(owner.getAddress());
136	        List<Owner> householdMembers = new ArrayList<>();
137	        for (Owner existing : this.clinicService.findAllOwners()) {
138	            if (lastNameKey.equals(householdKey(existing.getLastName()))
139	                && addressKey.equals(householdKey(existing.getAddress()))) {
140	                householdMembers.add(existing);
141	            }
142	        }
143	        if (!householdMembers.isEmpty()) {
144	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
145	                return new ResponseEntity<>(HttpStatus.CONFLICT);
146	            }
147	            String householdId = householdId(lastNameKey, addressKey);
148	            owner.setHouseholdId(householdId);
149	            for (Owner member : householdMembers) {
150	                if (!householdId.equals(member.getHouseholdId())) {
151	                    member.setHouseholdId(householdId);
152	                    this.clinicService.saveOwner(member);
153	                }
154	            }
155	        }
156	        owner.setTelephone(telephone);
157	        if (owner.getRegistrationDate() == null) {
158	            owner.setRegistrationDate(LocalDate.now());
159	        }
160	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
161	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
162	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
163	        this.clinicService.saveOwner(owner);
164	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
165	        headers.setLocation(UriComponentsBuilder.newInstance()
166	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
167	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
168	    }
169	
170	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
171	    @Override
172	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
173	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
174	        if (currentOwner == null) {
175	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
176	        }
177	        currentOwner.setAddress(ownerFieldsDto.getAddress());
178	        currentOwner.setCity(ownerFieldsDto.getCity());
179	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
180	        currentOwner.setLastName(ownerFieldsDto.getLastName());
181	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
182	        this.clinicService.saveOwner(currentOwner);
183	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
184	    }
185	
186	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
187	    @Transactional
188	    @Override
189	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
190	        Owner owner = this.clinicService.findOwnerById(ownerId);
191	        if (owner == null) {
192	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
193	        }
194	        this.clinicService.deleteOwner(owner);
195	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
196	    }
197	
198	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
199	    @Override
200	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
201	        Owner owner = this.clinicService.findOwnerById(ownerId);
202	        if (owner == null) {
203	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
204	        }
205	        HttpHeaders headers = new HttpHeaders();
206	        Pet pet = petMapper.toPet(petFieldsDto);
207	        owner.setId(ownerId);
208	        pet.setOwner(owner);
209	        pet.getType().setName(null);
210	        this.clinicService.savePet(pet);
211	        PetDto petDto = petMapper.toPetDto(pet);
212	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
213	            .buildAndExpand(pet.getId()).toUri());
214	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
215	    }
216	
217	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
218	    @Override
219	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
220	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
221	        if (currentOwner != null) {
222	            Pet currentPet = this.clinicService.findPetById(petId);
223	            if (currentPet != null) {
224	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
225	                currentPet.setName(petFieldsDto.getName());
226	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
227	                this.clinicService.savePet(currentPet);
228	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
229	            }
230	        }
231	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
232	    }
233	
234	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
235	    @Override
236	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
237	        HttpHeaders headers = new HttpHeaders();
238	        Visit visit = visitMapper.toVisit(visitFieldsDto);
239	        Pet pet = new Pet();
240	        pet.setId(petId);
241	        visit.setPet(pet);
242	        this.clinicService.saveVisit(visit);
243	        VisitDto visitDto = visitMapper.toVisitDto(visit);
244	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
245	            .buildAndExpand(visit.getId()).toUri());
246	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
247	    }
248	
249	
250	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
251	    @Override
252	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
253	        Owner owner = this.clinicService.findOwnerById(ownerId);
254	        if (owner != null) {
255	            Pet pet = owner.getPet(petId);
256	            if (pet != null) {
257	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
258	            }
259	        }
260	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
261	    }
262	
263	    /**
264	     * The maximum number of owners permitted per city. Owner creation is rejected once the
265	     * owner's city already contains this many owners.
266	     */
267	    private static final int MAX_OWNERS_PER_CITY = 50;
268	
269	    /**
270	     * Counts how many existing owners live in the given city, compared case-insensitively.
271	     * This is evaluated before the new owner is persisted, so the owner being created is not
272	     * included in the count.
273	     *
274	     * @param city the new owner's city
275	     * @return the number of existing owners in that city
276	     */
277	    private int countOwnersInCity(String city) {
278	        int count = 0;
279	        for (Owner existing : this.clinicService.findAllOwners()) {
280	            if (city.equalsIgnoreCase(existing.getCity())) {
281	                count++;
282	            }
283	        }
284	        return count;
285	    }
286	
287	    /**
288	     * Builds the customer code for a newly created owner, formatted
289	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first
290	     * three letters of the city, {@code LAST3} the upper-cased first three letters of
291	     * the last name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal
292	     * to one more than the number of owners already in that city.
293	     *
294	     * @param city     the owner's city
295	     * @param lastName the owner's last name
296	     * @return the assigned customer code (e.g. {@code 'SYD-SMI-0007'})
297	     */
298	    private String nextCustomerCode(String city, String lastName) {
299	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
300	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
301	        int sequence = 1;
302	        for (Owner existing : this.clinicService.findAllOwners()) {
303	            if (city.equalsIgnoreCase(existing.getCity())) {
304	                sequence++;
305	            }
306	        }
307	        return String.format("%s-%s-%04d", city3, last3, sequence);
308	    }
309	
310	    /**
311	     * Builds the membership number for a newly created owner, formatted
312	     * {@code '<customerCode>-M<YY>'} where {@code customerCode} is the owner's assigned
313	     * customer code and {@code YY} is the last two digits of the owner's registration
314	     * date year, zero-padded to two digits.
315	     *
316	     * @param customerCode     the owner's assigned customer code (e.g. {@code 'SYD-SMI-0007'})
317	     * @param registrationDate the owner's registration date
318	     * @return the assigned membership number (e.g. {@code 'SYD-SMI-0007-M26'})
319	     */
320	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
321	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
322	    }
323	
324	    /**
325	     * Counts how many existing owners share the given first and last name, compared
326	     * case-insensitively. This is evaluated before the new owner is persisted, so the
327	     * owner being created is not included in the count.
328	     *
329	     * @param firstName the new owner's first name
330	     * @param lastName  the new owner's last name
331	     * @return the number of existing owners with the same first and last name
332	     */
333	    private int countNamesakes(String firstName, String lastName) {
334	        int count = 0;
335	        for (Owner existing : this.clinicService.findAllOwners()) {
336	            if (firstName.equalsIgnoreCase(existing.getFirstName())
337	                && lastName.equalsIgnoreCase(existing.getLastName())) {
338	                count++;
339	            }
340	        }
341	        return count;
342	    }
343	
344	    /**
345	     * Canonical expansions applied to common street-type abbreviations during address
346	     * normalization. Keys and values are upper-cased so the lookup runs after the address
347	     * has itself been upper-cased.
348	     */
349	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
350	        "ST", "STREET",
351	        "RD", "ROAD",
352	        "AVE", "AVENUE");
353	
354	    /**
355	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
356	     * every run of internal whitespace is collapsed to a single space, the result is
357	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
358	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
359	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
360	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
361	     * returned and compared for household duplicates; an address that is blank once
362	     * normalized fails the required-field check.
363	     *
364	     * @param address the raw address value supplied by the client
365	     * @return the normalized address (empty string when {@code address} is null or blank)
366	     */
367	    private static String normalizeAddress(String address) {
368	        if (address == null) {
369	            return "";
370	        }
371	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
372	        if (collapsed.isEmpty()) {
373	            return "";
374	        }
375	        StringBuilder normalized = new StringBuilder(collapsed.length());
376	        for (String token : collapsed.split(" ")) {
377	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
378	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
379	            if (normalized.length() > 0) {
380	                normalized.append(' ');
381	            }
382	            normalized.append(expanded != null ? expanded : token);
383	        }
384	        return normalized.toString();
385	    }
386	
387	    /**
388	     * Normalizes a last name or address for household-duplicate comparison: leading and
389	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
390	     * single space and the result is lower-cased. Two owners are considered to share a
391	     * household when both their last names and addresses produce the same key.
392	     *
393	     * @param value the raw last name or address value
394	     * @return the normalized comparison key (empty string when {@code value} is null)
395	     */
396	    private static String householdKey(String value) {
397	        if (value == null) {
398	            return "";
399	        }
400	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
401	    }
402	
403	    /**
404	     * Derives the stable shared household identifier for the given normalized last name
405	     * and address keys. The identifier is deterministic — the same household (same
406	     * {@link #householdKey normalized} last name and address) always maps to the same
407	     * value — so every owner who joins a household is assigned an identical id. It is the
408	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
409	     * '<lastNameKey>|<addressKey>'}.
410	     *
411	     * @param lastNameKey the normalized last name key
412	     * @param addressKey  the normalized address key
413	     * @return the shared household identifier
414	     */
415	    private static String householdId(String lastNameKey, String addressKey) {
416	        String source = lastNameKey + "|" + addressKey;
417	        try {
418	            byte[] digest = MessageDigest.getInstance("SHA-256")
419	                .digest(source.getBytes(StandardCharsets.UTF_8));
420	            StringBuilder hex = new StringBuilder(digest.length * 2);
421	            for (byte b : digest) {
422	                hex.append(String.format("%02x", b));
423	            }
424	            return hex.substring(0, 12).toUpperCase();
425	        } catch (NoSuchAlgorithmException e) {
426	            throw new IllegalStateException("SHA-256 not available", e);
427	        }
428	    }
429	
430	    /**
431	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
432	     * and brackets are stripped. When the number already carries a leading {@code '+'}
433	     * and country code these are kept; otherwise Australia's country code {@code '+61'}
434	     * is assumed and a single leading {@code '0'} is dropped from the national digits.
435	     * The resulting number must have between 8 and 15 digits after the {@code '+'}.
436	     *
437	     * @param telephone the raw telephone value supplied by the client
438	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
439	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
440	     */
441	    private static String toE164(String telephone) {
442	        if (telephone == null) {
443	            return null;
444	        }
445	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
446	        String digits;
447	        if (cleaned.startsWith("+")) {
448	            digits = cleaned.substring(1);
449	        } else {
450	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
451	            digits = "61" + national;
452	        }
453	        return digits.matches("[0-9]{8,15}") ? "+" + digits : null;
454	    }
455	
456	    /**
457	     * Normalizes an owner email for creation. A present email must be a syntactically
458	     * valid address; the returned value is lower-cased.
459	     *
460	     * @param email the raw email value supplied by the client (never {@code null} here)
461	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
462	     *         address (signalling a 400 Bad Request)
463	     */
464	    private static String normalizeEmail(String email) {
465	        String trimmed = email.trim();
466	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
467	            return null;
468	        }
469	        return trimmed.toLowerCase();
470	    }
471	}
